/** Source replay with pure copies; no programmer registration or physical publication. */
@EventBusSubscriber(modid="vandorlabs")
public final class ProgrammerFoundationChecks {
 private static int checks;
 private static void need(boolean valid,String why){checks++;if(!valid)throw new AssertionError("Programmer foundation: "+why);}
 private static CompoundTag encoded(ItemStack stack,net.minecraft.core.HolderLookup.Provider registries){return stack.isEmpty()?new CompoundTag():NativeInventoryItems.write(stack,registries);}
 private static ItemStack captured(JsonElement value,net.minecraft.core.HolderLookup.Provider registries)throws Exception{var tag=TagParser.parseTag(value.getAsString());if(tag.getString("id").equals("minecraft:air")){need(tag.equals(TagParser.parseTag("{id:\"minecraft:air\",Count:1b,Damage:0s}")),"exact captured Source EMPTY descriptor");return ItemStack.EMPTY;}return NativeInventoryItems.legacy(tag,registries);}
 private static int n(JsonObject row,String key){return row.get(key).getAsInt();}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!"programmer-foundations".equals(System.getProperty("vandorlabs.transmitterPhase")))return;var server=event.getServer();try{
  JsonObject source;try(var reader=Files.newBufferedReader(Path.of(System.getenv("VANDOR_PROGRAMMER_REFERENCE")))){source=JsonParser.parseReader(reader).getAsJsonObject();}need(source.get("golden").getAsString().equals("ef75c4ffecd2e1b4c7b4ce4fb50c4bbf6894dc8ccd51e3202e2342e7476a9ce2"),"actual Source corpus");int cases=0;
  for(var value:source.getAsJsonArray("cases")){var r=value.getAsJsonObject();var m=r.getAsJsonObject("master");var i=r.getAsJsonObject("input");int company=ProgrammerPolicy.company(n(m,"kind"),n(m,"company"),m.get("master").getAsBoolean());boolean out=r.get("output").getAsBoolean();String problem=ProgrammerPolicy.problem(n(i,"kind"),n(i,"company"),n(i,"count"),out,n(m,"kind")!=0,company,r.get("journal").getAsBoolean());need(company==n(r,"company")&&problem.equals(r.get("problem").getAsString())&&problem.isEmpty()==r.get("canProgram").getAsBoolean(),"program decision "+cases);need(ProgrammerPolicy.copyProblem(n(i,"kind"),n(i,"company"),n(i,"count"),out?1:0,out?2:0,out?1:0).equals(r.get("copyProblem").getAsString()),"Copy decision");for(int slot=0;slot<3;slot++)need(ProgrammerPolicy.validSlot(slot,n(i,"kind"),n(i,"company"),i.get("master").getAsBoolean())==r.get("valid"+slot).getAsBoolean(),"slot decision");cases++;}
  var registries=server.registryAccess();int operations=0;for(var value:source.getAsJsonArray("operations")){var r=value.getAsJsonObject();var raw=r.getAsJsonArray("before");var master=captured(raw.get(0),registries);var input=captured(raw.get(1),registries);var target=captured(raw.get(2),registries);var a=encoded(master,registries);var b=encoded(input,registries);var c=encoded(target,registries);var draft=new NativeProgrammerDraft(false,r.get("journal").getAsBoolean(),"Draft title",List.of("Draft first","Draft second"));boolean copy=r.get("copy").getAsBoolean();String problem=copy?NativeProgrammerRules.copyProblem(input,target):NativeProgrammerRules.problem(master,input,target,draft);need(problem.isEmpty()==r.get("accepted").getAsBoolean(),"native eligibility "+operations);if(problem.isEmpty()){var result=copy?NativeProgrammerRules.committedCopy(input,target):NativeProgrammerRules.programmedCopy(master,input,draft);var expected=captured(r.getAsJsonArray("after").get(2),registries);need(result.getItem()==expected.getItem()&&result.getCount()==expected.getCount()&&NativeCredentialItems.company(result)==NativeCredentialItems.company(expected),"result company/kind/count");need(Objects.equals(NativeChipJournal.textData(result),NativeChipJournal.textData(expected))&&NativeChipJournal.master(result)==NativeChipJournal.master(expected),"result journal/master");need(NativeCredentialItems.legacyCredentialData(result).equals(NativeCredentialItems.legacyCredentialData(input)),"complete original envelope retained");}need(a.equals(encoded(master,registries))&&b.equals(encoded(input,registries))&&c.equals(encoded(target,registries)),"all physical owners unchanged by pure transform");operations++;}
  drafts();for(String imported:new String[]{"","master","journal","vehicle"})for(String current:new String[]{"","master","journal","vehicle"}){var raw=new CompoundTag();raw.putString("id","vandorlabs:data_chip");raw.putByte("Count",(byte)1);raw.putShort("Damage",(short)2);var tag=new CompoundTag();if(!imported.isEmpty())tag.putString("ChipType",imported);tag.putByteArray("VehicleDesign",new byte[]{3,17,29});raw.put("tag",tag);var stack=NativeInventoryItems.legacy(raw,registries);if(!current.isEmpty()){var data=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();data.putString("ChipType",current);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));}var before=encoded(stack,registries);boolean vehicle=(current.isEmpty()?imported:current).equals("vehicle");need(NativeChipJournal.vehicle(stack)==vehicle,"current/imported precedence");if(vehicle){need(!NativeProgrammerRules.problem(ItemStack.EMPTY,stack,ItemStack.EMPTY,NativeProgrammerDraft.empty()).isEmpty()&&!NativeProgrammerRules.copyProblem(stack,stack).isEmpty()&&!NativeProgrammerRules.validSlot(1,stack),"Vehicle operations unavailable");try{NativeProgrammerRules.programmedCopy(ItemStack.EMPTY,stack,NativeProgrammerDraft.empty());throw new AssertionError("Vehicle mutation accepted");}catch(IllegalArgumentException expected){}}need(before.equals(encoded(stack,registries)),"Vehicle bytes unchanged");}
  need(cases==21904&&operations==392,"complete corpus");System.out.println("[vandorlabs][programmer-foundations] PASS sourceCases="+cases+" sourceOperations="+operations+" checks="+checks);
 }catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][programmer-foundations] FAIL "+failure);}finally{server.halt(false);}}
 private static void drafts(){var raw=new CompoundTag();raw.putBoolean("Vehicle",true);raw.putBoolean("Journal",true);raw.putString("Title","x".repeat(100));raw.putString("ForeignEnvelope","OPAQUE");var pages=new ListTag();for(int i=0;i<12;i++)pages.add(StringTag.valueOf("y".repeat(700)));raw.put("Pages",pages);var before=raw.copy();for(boolean chip:new boolean[]{false,true}){var draft=NativeProgrammerDraft.read(raw,chip);need(draft.vehicle()==chip&&draft.journal()==chip&&draft.title().length()==40&&draft.pages().size()==8&&draft.pages().get(7).length()==512,"draft bounds/defaults");var saved=raw.copy();draft.write(saved);need(saved.getString("ForeignEnvelope").equals("OPAQUE")&&raw.equals(before),"foreign fields retained");var mutable=draft.entries();mutable[0]="mutation";need(!draft.pages().getFirst().equals("mutation"),"immutable pages");}need(NativeProgrammerDraft.read(new CompoundTag(),true).equals(NativeProgrammerDraft.empty()),"fresh draft");}
}
